/* Presentation of the same captured decision on screen, in PDF and offline HTML. */
(function () {
  'use strict';
  const a=window.VersionCompassAdvisor,esc=a.esc;
  const statuses={start:'Start a decision',not_covered:'Not covered',needs_review:'Evidence review needed',needs_facts:'User facts needed',version_gap:'Documented version gap',no_change:'No gap in these minimums',conditional:'Conditional next steps',conflicting:'Conflicting guidance',not_established:'Not established'};
  function refs(ids,result,print=false){return [...new Set(ids||[])].map(id=>{
    const index=result.sources.findIndex(source=>source.id===id);if(index<0)return '';
    const source=result.sources[index];return '<a class="advisor-citation" href="'+esc(print?'#advisor-source-'+id:source.url)+'"'+(print?'':' target="_blank" rel="noopener noreferrer"')+'>['+(index+1)+'] <span>'+esc(source.title)+'</span></a>';
  }).filter(Boolean).join(' · ');}
  function items(rows,result,print=false){return '<ul>'+rows.map(row=>'<li><strong>'+esc(row.text)+'</strong>'+(row.impact?'<p>'+esc(row.impact)+'</p>':'')+(row.sourceIds?.length?'<p class="advisor-refs">'+refs(row.sourceIds,result,print)+'</p>':'')+'</li>').join('')+'</ul>';}
  function checks(result,print=false){return result.checks.length?'<section class="advisor-brief-section"><h3>Reported versions against documented minimums</h3><p>A minimum is a prerequisite, not a recommended target or proof of full compatibility.</p><div class="advisor-table-scroll" role="region" aria-label="Version prerequisite comparison" tabindex="0"><table><caption>Self-reported versions; only the stated minimum is compared.</caption><thead><tr><th scope="col">Component</th><th scope="col">You report</th><th scope="col">Documented minimum</th><th scope="col">Comparison</th></tr></thead><tbody>'+result.checks.map(row=>'<tr><th scope="row">'+esc(row.label)+'</th><td>'+esc(row.reported)+'</td><td>'+esc(row.minimum)+'<br>'+refs(row.sourceIds,result,print)+'</td><td>'+esc({meets:'Meets this minimum only',below:'Below this minimum',unknown:'Cannot compare yet',conflicting:'Sources disagree'}[row.outcome])+(row.reportedNote?'<p>'+esc(row.reportedNote)+'</p>':'')+'</td></tr>').join('')+'</tbody></table></div></section>':'';}
  function reviewHTML(result){const review=result.review;if(!review)return '';
    return '<div class="advisor-review-stamps"><p><strong>Brief created</strong><br>'+esc(result.createdAt)+' UTC</p><p><strong>Recorded source checks</strong><br>'+esc(review.checked?.filter(Boolean).join(', ')||'A new review is needed')+'</p><p><strong>Recorded claim / section assessments</strong><br>'+esc(review.assessed?.filter(Boolean).join(', ')||'A new review is needed')+'</p></div><p class="advisor-fineprint">This brief uses dated assessed evidence. It does not recheck Splunk pages when you build it. The creation date is not a new source or claim review.'+(review.due?' Advisor review due by '+esc(review.due)+' under its published review policy.':'')+'</p>';
  }
  function resultHTML(result,print=false){
    const current=result.conflicts.filter(row=>row.affectsDecision),other=result.conflicts.filter(row=>!row.affectsDecision);
    const conflict=row=>'<aside class="advisor-conflict"><h3>'+esc(row.title)+'</h3><p>'+esc(row.scope)+'</p><p>'+esc(row.text)+'</p><p><strong>Decision impact:</strong> '+esc(row.impact)+'</p><p>'+refs(row.sourceIds,result,print)+'</p></aside>';
    return '<article class="advisor-result" data-outcome="'+esc(result.status)+'"><header class="advisor-outcome"><p class="advisor-status">'+esc(statuses[result.status])+'</p><h2>'+esc(result.title)+'</h2><p>'+esc(result.summary)+'</p></header>'+current.map(conflict).join('')+
      '<section class="advisor-brief-section"><h3>What this brief covers</h3><p>'+esc(result.goal?.coverage||result.summary)+'</p>'+(result.goal?'<p><strong>Boundary:</strong> '+esc(result.goal.exclusions)+'</p>':'')+'</section>'+
      (result.established.length?'<section class="advisor-brief-section"><h3>What the assessed documentation establishes</h3>'+items(result.established,result,print)+'</section>':'')+checks(result,print)+
      '<div class="advisor-gap-grid"><section class="advisor-brief-section"><h3>Missing facts about your environment</h3>'+(result.missingFacts.length?items(result.missingFacts,result,print):'<p>No additional user-fact gap was identified for this limited comparison. This is not an environment inspection.</p>')+'</section><section class="advisor-brief-section"><h3>Missing or limited assessed evidence</h3>'+(result.missingEvidence.length?items(result.missingEvidence,result,print):'<p>No additional evidence gap is listed for the bounded facts above. All stated qualifications still apply.</p>')+'</section></div>'+
      (result.actions.length?'<section class="advisor-next"><h3>What to verify or do next</h3><ol>'+result.actions.map(row=>'<li><h4>'+esc(row.title)+'</h4><p>'+esc(row.detail)+'</p>'+(row.sourceIds?.length?'<p>'+refs(row.sourceIds,result,print)+'</p>':'')+(row.handoff?(print?'<p><a href="/?product=platform&amp;platform=enterprise">Open the Enterprise Release Guide</a>. The reported context above is not embedded in this link.</p>':'<button type="button" class="advisor-primary" data-advisor-guide>Open Release Guide with private context</button><p class="advisor-fineprint">The context note stays in this tab. No current version or target is added to the link.</p>'):'')+'</li>').join('')+'</ol></section>':'')+
      (other.length?'<details class="advisor-history"'+(print?' open':'')+'><summary>A separate Cloud source conflict</summary>'+other.map(conflict).join('')+'</details>':'')+
      (result.history.length?'<details class="advisor-history"'+(print?' open':'')+'><summary>Historical wording already corrected</summary>'+result.history.map(row=>'<h3>'+esc(row.title)+'</h3><p>'+esc(row.text)+'</p><p>'+refs(row.sourceIds,result,print)+'</p>').join('')+'</details>':'')+
      (result.record?'<details class="advisor-history"'+(print?' open':'')+'><summary>Read the assessed capability and its full limits</summary><h3>'+esc(result.record.title)+'</h3><p>'+esc(result.record.version)+' · '+esc(result.record.stage)+'</p><ul>'+result.record.requirements.map(row=>'<li>'+esc(row)+'</li>').join('')+'</ul><p>'+esc(result.record.qualification)+'</p><p>Capability record assessed '+esc(result.record.verified)+'. Later section-specific assessments below do not advance every prerequisite date.</p></details>':'')+
      '<p class="advisor-boundary">Self-reported context only. This brief does not establish complete compatibility, entitlement, tenant availability, health, compliance or customer authorization.</p></article>';
  }
  function sources(result,print=false){return result.sources.length?'<ol class="advisor-source-list">'+result.sources.map(source=>'<li id="'+(print?'advisor-source-':'advisor-screen-source-')+''+esc(source.id)+'"><h3>'+esc(source.title)+'</h3><a href="'+esc(source.url)+'">'+esc(source.url)+'</a><p><strong>Supporting section:</strong> '+esc(source.section)+'</p><p>Source checked '+esc(source.checked)+' · Section assessed '+esc(source.reviewed)+'</p><p><strong>Assessment scope:</strong> '+esc(source.scope||source.section)+'</p></li>').join('')+'</ol>':'<p>No factual capability path is offered while this decision needs reassessment.</p>';}
  function profile(result){return '<dl class="advisor-profile-summary">'+a.fields(result.state).map(key=>'<div><dt>'+esc(a.labels[key])+'</dt><dd>'+esc(a.choices[key]?.[result.state[key]]|| (key==='region'?(window.VersionCompassAIAvailability.regions().find(row=>row.id===result.state[key])?.label||(result.state[key]==='other'?'Not in the assessed list':'Unknown')):result.state[key]||'Unknown'))+'</dd></div>').join('')+'</dl>';}
  function report(result){
    const body='<article><header class="report-title"><p>VERSION COMPASS / ADVISOR · WORK IN PROGRESS</p><h1>Decision brief</h1><p>'+esc(result.goal?.title||result.title)+'</p></header><section class="report-section"><h2>Self-reported context</h2><p>These inputs are unverified. A goal link excludes them; this preserved brief deliberately includes them.</p>'+profile(result)+'</section><section class="report-section">'+resultHTML(result,true)+'</section><section class="report-section"><h2>Evidence dates and review scope</h2>'+reviewHTML(result)+sources(result,true)+'</section><section class="report-section"><h2>Current coverage and exclusions</h2><p>Only previously assessed published Splunk documentation supports factual claims. Licensing, sizing, ingest troubleshooting and operational advice without sufficient assessed evidence are outside this build. No runtime model or automatic environment inspection is used.</p></section></article>';
    return '<div class="edition-report advisor-report">'+(window.VersionCompassReports?.decorate(body)||body)+'</div>';
  }
  Object.assign(a,{statuses,refs,checks,reviewHTML,resultHTML,sources,profile,report});
}());
